INSERT INTO app.attraction_catalog (partner_id, public_name, description, location, category, image_url, accessibility_information, is_pass_eligible, is_published, display_order, created_at, updated_at)
VALUES
('TEMPLE-01', 'Wat Rong Khun (White Temple)', 'Restored and envisioned by National Artist Chalermchai Kositpipat, this former small temple was transformed into a stunning white masterpiece. The design incorporates intricate mirrors reflecting light, contemporary art, and symbolic Buddhist iconography representing the journey from the hell of human desire to ultimate enlightenment.', 'Chiang Rai, Thailand', 'TEMPLE', '/images/wat-rong-khun.jpg', 'Parking available; wheelchair access should be confirmed', true, true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('TEMPLE-02', 'Wat Rong Suea Ten (Blue Temple)', 'A striking contemporary temple covered in deep sapphire blue and golden yellow highlights, created by Phuttha Kabkaew (a student of Chalermchai Kositpipat). Famous for its vivid modern murals covering the walls and a large, serene white Buddha image seated at the head of the hall.', 'Chiang Rai, Thailand', 'TEMPLE', '/images/wat-rong-suea-ten.jpg', 'Parking and access facilities should be confirmed', true, true, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('TEMPLE-03', 'Wat Huay Pla Kang', 'A famous hilltop temple complex known for its extraordinary nine-tiered pagoda (Phra Maha Chedi) combining Lanna and Chinese architecture, along with a colossal white statue of Guanyin (Goddess of Mercy) overlooking the valley. Visitors can take an elevator inside the statue to enjoy panoramic views.', 'Chiang Rai, Thailand', 'TEMPLE', '/images/wat-huay-pla-kang.jpg', 'Hilltop location; wheelchair access should be confirmed', true, true, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('TEMPLE-04', 'Wat Phra Singh Chiang Rai', 'A revered historic temple situated in the heart of Chiang Rai city centre. Dating back to the 14th century, it once housed the sacred Phra Singh Buddha image and features classical Lanna-style wooden structures, intricate carvings, and a beautiful golden chedi.', 'Chiang Rai, Thailand', 'TEMPLE', '/images/wat-phra-singh.jpg', 'Accessibility facilities should be confirmed', true, true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('TEMPLE-05', 'Wat Phra Kaew Chiang Rai', 'One of northern Thailand''s most historic temples, famous as the site where the sacred Emerald Buddha was first discovered in 1434 after lightning struck its chedi. The complex also houses an exquisite museum showcasing valuable Lanna religious art, antiques, and a new Emerald Buddha replica.', 'Chiang Rai, Thailand', 'TEMPLE', '/images/wat-phra-kaew.jpg', 'Accessibility facilities should be confirmed', true, true, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('MUSEUM-01', 'Baan Dam Museum', 'Created by national artist Thawan Duchanee, this distinctive complex consists of over 40 dark wooden structures inspired by Lan Xang, Lanna, and Suvarnabhumi architecture. It serves as an art space displaying unique collections of animal bones, horns, skins, and intricate silverwork in the Lao House.', 'Chiang Rai, Thailand', 'MUSEUM', '/images/baan-dam.jpg', 'Walking paths; wheelchair access should be confirmed', true, true, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('MUSEUM-02', 'Oub Kham Museum', 'A private heritage museum exhibiting rare and irreplaceable Lanna artefacts, royal regalia, ancient costumes, and tribal jewellery collected from northern Thailand, Myanmar, Laos, and southwestern China, preserving the rich cultural identity of the golden Golden Triangle region.', 'Chiang Rai, Thailand', 'MUSEUM', '/images/oub-kham-museum.jpg', 'Accessibility facilities should be confirmed', true, true, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('MUSEUM-03', 'Hill Tribe Museum', 'An educational museum run by the Population and Community Development Association (PDA). It introduces visitors to the history, traditional attire, crafts, slash-and-burn agricultural practices, and daily life of the major hill tribe communities across northern Thailand.', 'Chiang Rai, Thailand', 'MUSEUM', '/images/hill-tribe-museum.jpg', 'Audio-visual exhibits and multilingual learning resources', true, true, 8, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('NATURE-01', 'Singha Park Chiang Rai', 'Thailand''s largest agro-tourism destination spanning over 8,000 rai (approx 3.2 sq km). Features scenic rolling hills, tea plantation tours, fruit orchards, African wildlife areas (giraffes & zebras), cycling trails, adventure ziplining, and seasonal hot air balloon festivals.', 'Chiang Rai, Thailand', 'NATURE', '/images/singha-park.jpg', 'Parking and sightseeing tram available; accessibility details should be confirmed', true, true, 9, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('CULTURE-01', 'Mae Fah Luang Art and Cultural Park', 'A peaceful botanical garden and cultural centre featuring traditional teakwood Lanna structures, including Haw Kham (The Golden Pavilion). It displays historical wooden religious craftsmanship, antique lanterns, and Lanna art surrounding a serene lotus pond.', 'Chiang Rai, Thailand', 'CULTURAL', '/images/mae-fah-luang-art-park.jpg', 'Garden paths and exhibition access to be confirmed', true, true, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('MUSEUM-05', 'Chiang Saen National Museum', 'A national museum located near the ancient city walls of Chiang Saen. It preserves and displays precious archaeological finds, stone inscriptions, Lanna-style bronze Buddha images, and historical relics excavated from ancient temples along the Mekong River basin.', 'Chiang Saen, Chiang Rai, Thailand', 'MUSEUM', '/images/chiang-saen-museum.jpg', 'Entrance ramp reported; upper-floor access may be limited by stairs. Confirm facilities with the museum.', true, true, 11, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('CULTURE-02', 'Hall of Opium', 'A world-class interactive exhibition museum located near the Golden Triangle. It presents the comprehensive 5,000-year history of opium—from its medicinal origins and trade wars to its social impacts and regional rehabilitation projects initiated by the Royal Project.', 'Chiang Saen, Chiang Rai, Thailand', 'MUSEUM', '/images/hall-of-opium.jpg', 'Indoor exhibition; accessibility details to be confirmed', true, true, 12, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('NATURE-02', 'Choui Fong Tea Plantation', 'Located in Mae Chan district, this famous 1.6 sq km hillside tea plantation features neatly manicured green tea terraces cascading down the mountainside. Visitors can observe tea leaf picking and relax at modern architectural cafes serving fresh tea, cakes, and light meals.', 'Mae Chan, Chiang Rai, Thailand', 'NATURE', '/images/choui-fong.jpg', 'Sloping tea plantation terrain; access details to be confirmed', true, true, 13, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('NATURE-03', 'Mae Fah Luang Garden, Doi Tung', 'A beautifully manicured high-altitude botanical garden located on Doi Tung mountain. Built to honor HRH Princess Srinagarindra, it displays exotic winter flowers, native northern orchids, fountains, and sculptures amid cool mountain air year-round.', 'Mae Fa Luang, Chiang Rai, Thailand', 'NATURE', '/images/mae-fah-luang-garden.jpg', 'Outdoor garden paths; terrain varies', true, true, 14, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('NATURE-04', 'Tham Luang–Khun Nam Nang Non National Park', 'A famous national park encompassing forested mountains, natural emerald lagoons, and the cave complex of Tham Luang. Known globally for the international 2018 cave rescue operation, featuring an exhibition center and memorial dedicated to the rescue efforts.', 'Mae Sai, Chiang Rai, Thailand', 'NATURE', '/images/tham-luang.jpg', 'Cave and park access depends on designated routes and conditions', true, true, 15, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('ART-01', 'Art Bridge Chiang Rai (Khua Silpa)', 'A vibrant riverside art space established by local Chiang Rai artists to support and cultivate northern Thai contemporary art. The complex houses rotation galleries, souvenir shops selling original art prints, workshop areas, and a picturesque riverside cafe.', 'Rim Kok, Mueang Chiang Rai, Thailand', 'ART_GALLERY', '/images/art-bridge.jpg', 'Accessibility facilities to be confirmed', true, true, 16, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('ART-02', 'Chiangrai Contemporary Art Museum', 'A dedicated modern gallery space promoting contemporary fine arts. It features rotated exhibitions from emerging local Chiang Rai creators as well as acclaimed international artists, serving as a hub for artistic inspiration and creative dialogue in northern Thailand.', 'Rim Kok, Mueang Chiang Rai, Thailand', 'ART_GALLERY', '/images/chiangrai-contemporary-art.jpg', NULL, true, true, 17, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('partner-gt', 'Golden Triangle', 'The famous geographical border confluence where Thailand, Laos, and Myanmar meet along the Mekong and Ruak Rivers. Historically coined by the CIA, it serves as a major regional trade crossroads, offering river boat tours and views of three countries at once.', 'Chiang Saen, Chiang Rai, Thailand', 'LANDMARK', '/images/golden-triangle.jpg', 'Wheelchair accessible', false, true, 18, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

INSERT INTO app.attraction_catalog (partner_id, public_name, description, location, category, image_url, accessibility_information, map_url, is_pass_eligible, is_published, display_order, created_at, updated_at) VALUES
('RES-001', 'Breakfast factory', 'A welcoming breakfast and brunch café in the heart of Chiang Rai, Breakfast Factory is known for its diverse selection of freshly prepared dishes combining New-American breakfast favorites with local Thai flavors. The menu features a variety of options, including homemade sourdough, avocado toast, eggs, pancakes, waffles, sandwiches, and healthy breakfast bowls. With its relaxed atmosphere, generous portions, and emphasis on fresh ingredients, the café offers a comfortable place for visitors to enjoy a satisfying morning meal and experience Chiang Rai''s vibrant café culture.', 'Chiang Rai, Thailand', 'RESTAURANT', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRQyRpOsr9pKmVwo6bCW6b8Q_F00cw2ybAfaJzhgtzVzKVhHR4bEpqBAJ8&s=10', 'Wheelchair accessibility is listed as available. The restaurant also offers indoor and outdoor seating. However, specific details about step-free entrance access, accessible restrooms, and wheelchair-friendly pathways have not been confirmed.', 'https://maps.app.goo.gl/5PbmMkNCAMtYptjN9', true, true, 19, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('RES-002', 'Malongder', 'Located in Ban Du, Chiang Rai, Ma Long Der is a charming restaurant specializing in traditional Northern Thai cuisine with a modern fusion twist. The restaurant brings local Lanna flavors to life through thoughtfully crafted dishes, beautiful food presentation, and carefully selected local ingredients. Set in a relaxing atmosphere inspired by contemporary Lanna design, it offers guests a unique dining experience where traditional Northern Thai food meets art, culture, and creativity. A must-visit destination for anyone looking to discover the authentic flavors of Chiang Rai in a fresh and modern way.', 'Ban Du, Chiang Rai, Thailand', 'RESTAURANT', 'https://paiduaykan.com/wp-content/uploads/2021/11/8-SON06590.jpg', 'Accessibility facilities have not been officially confirmed. Parking is available at the restaurant. Visitors with wheelchairs or mobility difficulties are advised to contact the restaurant in advance to confirm entrance access, seating arrangements, and restroom facilities.', 'https://maps.app.goo.gl/cmBRQECyLa2DLUWr7', true, true, 20, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('RES-003', 'Aek Ocha', 'Ek Ocha is one of the most famous and well-known restaurants in Chiang Rai. It has been serving delicious food for over 40 years. The restaurant offers a variety of dishes, including Northern Thai, Chinese, Thai, and fusion cuisine. One of its must-try signature dishes is Seafood Yen Ta Fo Hot Pot. The food is mainly Chinese-style but has rich and spicy flavors that make it unique. Ek Ocha is a favorite among local people and is also a restaurant that tourists should not miss when visiting Chiang Rai.', 'Rim Kok, Mueang Chiang Rai, Thailand', 'RESTAURANT', 'https://www.ktc.co.th/upload/pub/media/Article/08/ktc-China-Garden-800x533.webp', 'Conveniently located in Chiang Rai city, easily accessible by car or public transportation, with parking available for visitors.', 'https://maps.app.goo.gl/Ef65cpj4mmdbFt3HA', true, true, 21, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('RES-004', 'Homchan', 'Homchan is a popular restaurant and café in Chiang Rai, offering a complete dining experience in one place. Visitors can enjoy a variety of Northern Thai dishes, refreshing drinks, and delicious bakery items. It is a perfect place for lunch, an afternoon coffee break, or taking beautiful photos for social media.', 'Chiang Rai, Thailand', 'RESTAURANT', 'https://www.drivehub.com/blog/wp-content/uploads/2024/05/05-4-1024x576.jpg', 'Conveniently located in Chiang Rai, easily accessible by car, with a comfortable dining area, café space, and parking facilities for visitors.', 'https://maps.app.goo.gl/5KdtM8s4gjJ8YFc37', true, true, 22, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('HOTEL-001', 'Le Méridien Chiang Rai Resort', 'Le Méridien Chiang Rai Resort is a luxurious 5-star riverside resort located along the Mae Kok River. Surrounded by beautiful gardens and peaceful natural scenery, the resort offers comfortable rooms, excellent dining, a swimming pool, a spa, and a fitness center. It is a perfect place for relaxation, romantic getaways, and enjoying the beautiful nature of Chiang Rai.', 'Chiang Rai, Thailand', 'HOTEL', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/13/12/db/le-meridien-chiang-rai.jpg?w=700&h=400&s=1', 'Conveniently located approximately 10 minutes from Chiang Rai International Airport and 15 minutes from the city center. The resort is easily accessible by car and offers complimentary on-site parking, elevators, wheelchair-accessible facilities, and accessible guest rooms.', 'https://www.google.com/maps/place/Le+M%C3%A9ridien+Chiang+Rai+Resort,+Thailand/@19.9222354,99.8542009,17z/data=!3m1!4b1!4m9!3m8!1s0x30d706fc54952959:0x35d94e44c6c283d4!5m2!4m1!1i2!8m2!3d19.9222354!4d99.8542009!16s%2Fg%2F1tf21j7c?entry=ttu&g_ep=EgoyMDI2MTEwMi4wIKXMDSoASAFQAw%3D%3D', true, true, 23, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('HOTEL-002', 'The Riverie by Katathani', 'The Riverie by Katathani is a luxurious 5-star riverside resort located in the heart of Chiang Rai. Situated on a beautifully landscaped island in the Kok River, the resort offers stunning river views, elegant rooms, and a peaceful atmosphere. It features several restaurants, swimming pools, a mini water park, a spa, and family-friendly activities. It is an ideal destination for families, couples, and travelers looking for a relaxing and memorable stay.', 'Chiang Rai, Thailand', 'HOTEL', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/26/f9/23/fe/the-riverie-by-katathani.jpg?w=1000&h=-1&s=1', 'Conveniently located in Chiang Rai city center, approximately 15 minutes by car from Mae Fah Luang–Chiang Rai International Airport. The resort is easily accessible by private car, with complimentary on-site parking, airport transfer services, and wheelchair-accessible facilities.', 'https://www.google.com/maps/place/The+Riverie+by+Katathani+Chiang+Rai/@19.9174144,99.8269884,17z/data=!3m1!4b1!4m9!3m8!1s0x30d7074a4c612c41:0xe53a354e4a02d059!5m2!4m1!1i2!8m2!3d19.9174144!4d99.8269884!16s%2Fg%2F11jdmj1psf?entry=ttu&g_ep=EgoyMDI2MTEwMi4wIKXMDSoASAFQAw%3D%3D', true, true, 24, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('HOTEL-003', 'Rommai Villa', 'Rommai Villa Chiang Rai is a charming boutique villa located in the peaceful Ban Du area of Chiang Rai. Surrounded by beautiful gardens, greenery, and mountain views, the villa offers a relaxing atmosphere with a traditional Thai-style design. Guests can enjoy comfortable rooms, delicious breakfast, free bicycle rentals, and friendly service. It is an ideal place for couples and travelers who want to relax and experience the natural beauty of Chiang Rai.', 'Chiang Rai, Thailand', 'HOTEL', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/a8/e8/dd/rommai-villa.jpg?w=700&h=400&s=1', 'Conveniently located near Chiang Rai Rajabhat University, approximately 10 minutes by car from Mae Fah Luang–Chiang Rai International Airport and 15 minutes from the city center. The villa is accessible by car and offers free private parking, complimentary airport shuttle service upon request, and bicycle rentals. Please note that the property does not have an elevator.', 'https://www.google.com/maps/place/Rommai+Villa+Chiang+Rai/@19.9849034,99.8428383,17z/data=!3m1!4b1!4m9!3m8!1s0x30d7012f13ab1365:0x8b7d4766c6979b02!5m2!4m1!1i2!8m2!3d19.9849034!4d99.8428383!16s%2Fg%2F11gvzby44g?entry=ttu&g_ep=EgoyMDI2MTEwMi4wIKXMDSoASAFQAw%3D%3D', true, true, 25, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('HOTEL-004', 'One Budget Hotel Chiangrai Stadium', 'One Budget Hotel Chiangrai Stadium is a modern and affordable hotel located in Chiang Rai. The hotel offers clean, comfortable rooms with a simple and contemporary design. Guests can enjoy essential facilities such as air conditioning, free Wi-Fi, a refrigerator, an elevator, and a 24-hour front desk. It is a great choice for budget-conscious travelers looking for a comfortable and convenient place to stay.', 'Chiang Rai, Thailand', 'HOTEL', 'https://cf.bstatic.com/xdata/images/hotel/max1024x768/327200747.jpg?k=55754a416565a61d48a078e08558d445d6468496ff9bf17028f23b7d4568652a&o=', 'Conveniently located in the Rop Wiang area of Chiang Rai, approximately 10–15 minutes by car from the city center and around 10–20 minutes from Mae Fah Luang–Chiang Rai International Airport, depending on traffic. The hotel is easily accessible by private car or taxi and provides free on-site parking, an elevator, wheelchair-accessible parking, and a step-free entrance.', 'https://www.google.com/maps/place/One+Budget+Hotel+Chiangrai+Stadium/@19.9073929,99.8533067,17z/data=!4m9!3m8!1s0x30d7063883f6ba53:0xac97c2b983b4700d!5m2!4m1!1i2!8m2!3d19.9073929!4d99.8558816!16s%2Fg%2F11ry5c9x3m?entry=ttu&g_ep=EgoyMDI2MTEwMi4wIKXMDSoASAFQAw%3D%3D', true, true, 26, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

